package com.phoenix.business.web;import com.phoenix.business.domain.*;import com.phoenix.business.service.ReportService;import lombok.RequiredArgsConstructor;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.time.LocalDate;
@RestController @RequestMapping("/api/reports") @RequiredArgsConstructor @PreAuthorize("hasAnyRole('OWNER','ADMIN')") public class ReportController {private final ReportService reports;@GetMapping(value="/members.xlsx",produces="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")public ResponseEntity<byte[]> members(@RequestParam(required=false)Member.Status status)throws Exception{return file("members.xlsx",reports.members(status));}@GetMapping(value="/payments.xlsx",produces="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")public ResponseEntity<byte[]> payments(@RequestParam(required=false)LocalDate from,@RequestParam(required=false)LocalDate to,@RequestParam(required=false)Payment.Method method)throws Exception{return file("payments.xlsx",reports.payments(from,to,method));}@GetMapping(value="/attendance.xlsx",produces="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")public ResponseEntity<byte[]> attendance(@RequestParam(required=false)LocalDate from,@RequestParam(required=false)LocalDate to,@RequestParam(required=false)Long memberId)throws Exception{return file("attendance.xlsx",reports.attendance(from,to,memberId));}@GetMapping(value="/expiring.xlsx",produces="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")public ResponseEntity<byte[]> expiring(@RequestParam(required=false)LocalDate from,@RequestParam(required=false)LocalDate to)throws Exception{return file("expiring-memberships.xlsx",reports.expiring(from,to));}@GetMapping(value="/revenue.xlsx",produces="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")public ResponseEntity<byte[]> revenue(@RequestParam(required=false)LocalDate from,@RequestParam(required=false)LocalDate to,@RequestParam(required=false)Payment.Method method)throws Exception{return file("revenue-summary.xlsx",reports.revenue(from,to,method));}private ResponseEntity<byte[]> file(String n,byte[] b){return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+n+"\"").body(b);}}
